public int notifications(int[] expenditure, int d) {
    int n = expenditure.length;
    int notifications = 0;
    for (int i = d; i < n; i++) {
        int[] window = Arrays.copyOfRange(expenditure, i - d, i);
        Arrays.sort(window);
        int doubledMedian = (d % 2 == 1)
            ? 2 * window[d / 2]
            : window[d / 2 - 1] + window[d / 2];
        if (expenditure[i] >= doubledMedian) {
            notifications++;
        }
    }
    return notifications;
}

