public int notifications(int[] expenditure, int d) {
    int n = expenditure.length;
    int[] count = new int[201];
    for (int i = 0; i < d; i++) {
        count[expenditure[i]]++;
    }
    int notifications = 0;
    for (int i = d; i < n; i++) {
        int doubledMedian = doubledMedian(count, d);
        if (expenditure[i] >= doubledMedian) {
            notifications++;
        }
        count[expenditure[i - d]]--;
        count[expenditure[i]]++;
    }
    return notifications;
}

private int doubledMedian(int[] count, int d) {
    if (d % 2 == 1) {
        return 2 * valueAtRank(count, d / 2 + 1);
    }
    return valueAtRank(count, d / 2) + valueAtRank(count, d / 2 + 1);
}

private int valueAtRank(int[] count, int rank) {
    int seen = 0;
    for (int v = 0; v <= 200; v++) {
        seen += count[v];
        if (seen >= rank) {
            return v;
        }
    }
    return 200;
}

